def solve(inp):
    n=len(inp); m=len(inp[0])
    # find band rows (rows that are uniformly a single nonzero color != pattern color... 3s)
    band=[r for r in range(n) if all(v==3 for v in inp[r])]
    # infer tile shape: rel row rr = r%5, rel col cc = c%5, from cells==2 outside band
    shape={}
    for r in range(n):
        if r in band: continue
        for c in range(m):
            if inp[r][c]==2:
                shape.setdefault((r%5,c%5),0)
    # verify consistency: no cell is 2 with (r%5,c%5) not in shape (outside band) - trivially true by construction
    # check that all shape cells with same r%5 agree across anchors: count mismatches
    pred=lambda r,c:(r%5,c%5) in shape
    mism=0
    for r in range(n):
        if r in band: continue
        for c in range(m):
            if inp[r][c]==2 and not pred(r,c): mism+=1
            if inp[r][c]==0 and pred(r,c): mism+=1  # missing tiles = zeros; count separately
    out=[row[:] for row in inp]
    # band rows: which diagonal rows 6i fall in band
    bandset=set(band)
    for r in band:
        for c in range(m):
            out[r][c]=0
    for i in range(n):
        r=6*i
        if r>=n: break
        for k in range(m):
            c=6*k
            if c>=m: break
            if pred(r,c):
                # ensure tile exists: anchor row 5*i tile? tile anchor rows: block containing r
                br=(r//5)*5
                ac=(c//5)*5
                tile_exists=any(inp[br+rr][ac+cc]==2 for rr in range(4) for cc in range(4) if br+rr<n and ac+cc<m and (br+rr)%5==rr and (ac+cc)%5==cc and br+rr not in bandset)
                if r in bandset:
                    # restore full tile in band
                    for rr in range(4):
                        for cc in range(4):
                            rr2,cc2=br+rr,ac+cc
                            if rr2<n and cc2<m and (rr,cc) in shape:
                                out[rr2][cc2]=2
                    out[r][c]=8
                elif tile_exists:
                    out[r][c]=8
    return out,mism

