def solve_b9ff20f9(inp):
    """ARC task-b9ff20f9 (SOLVED, verified exact on 1 demo).
    Rule: 5-periodic 4-row tile tiling (rows 0-3 mod 5, anchors cols 0 mod 5).
    A 4-row band of constant 3s hides tiles. Output: restore in band only tiles
    whose block contains diagonal row r=6i; recolor to 8 pattern cells at (6i,6k)
    where tile exists (or restored); other band cells -> 0; missing tiles elsewhere stay missing.
    """
    n, m = len(inp), len(inp[0])
    band = [r for r in range(n) if all(v == 3 for v in inp[r])]
    shape = set()
    for r in range(n):
        if r in band: continue
        for c in range(m):
            if inp[r][c] == 2:
                shape.add((r % 5, c % 5))
    pred = lambda r, c: (r % 5, c % 5) in shape
    out = [row[:] for row in inp]
    bandset = set(band)
    for r in band:
        for c in range(m):
            out[r][c] = 0
    def tile_exists(br, ac):
        return any(inp[br+rr][ac+cc] == 2 for rr in range(4) for cc in range(4)
                   if br+rr < n and ac+cc < m and br+rr not in bandset and (rr, cc) in shape)
    for i in range((n + 5) // 6 + 1):
        r = 6 * i
        if r >= n: break
        for k in range((m + 5) // 6 + 1):
            c = 6 * k
            if c >= m: break
            if not pred(r, c): continue
            br, ac = (r // 5) * 5, (c // 5) * 5
            if r in bandset:
                for rr in range(4):
                    for cc in range(4):
                        if br+rr < n and ac+cc < m and (rr, cc) in shape:
                            out[br+rr][ac+cc] = 2
                out[r][c] = 8
            elif tile_exists(br, ac):
                out[r][c] = 8
    return out
